// Self-checking testbench for w1c32 (generated by axilgen.py)
// iverilog -g2012 -o tb w1c32_tb.v w1c32.v && vvp tb
`default_nettype none
module tb;
    reg clk = 0, rstn = 0;
    always #5 clk = ~clk;
    reg         awvalid = 0, wvalid = 0, bready = 0, arvalid = 0, rready = 0;
    reg  [31:0] awaddr = 0, araddr = 0, wdata = 0;
    reg  [3:0]  wstrb = 4'hF;
    wire        awready, wready, bvalid, arready, rvalid;
    wire [1:0]  bresp, rresp;
    wire [31:0] rdata;
    reg  [31:0] i_ev_e = 0;
    wire [31:0] o_p_go;
    wire        o_irq;

    w1c32 #(.C_AXI_ADDR_WIDTH(32)) dut (
        .S_AXI_ACLK(clk), .S_AXI_ARESETN(rstn),
        .S_AXI_AWVALID(awvalid), .S_AXI_AWREADY(awready), .S_AXI_AWADDR(awaddr), .S_AXI_AWPROT(3'd0),
        .S_AXI_WVALID(wvalid), .S_AXI_WREADY(wready), .S_AXI_WDATA(wdata), .S_AXI_WSTRB(wstrb),
        .S_AXI_BVALID(bvalid), .S_AXI_BREADY(bready), .S_AXI_BRESP(bresp),
        .S_AXI_ARVALID(arvalid), .S_AXI_ARREADY(arready), .S_AXI_ARADDR(araddr), .S_AXI_ARPROT(3'd0),
        .S_AXI_RVALID(rvalid), .S_AXI_RREADY(rready), .S_AXI_RDATA(rdata), .S_AXI_RRESP(rresp),
        .i_ev_e(i_ev_e),
        .o_p_go(o_p_go),
        .o_irq(o_irq)
    );

    integer cnt_o_p_go = 0;
    reg  [31:0] last_o_p_go = 0;
    always @(posedge clk) if (|o_p_go) begin cnt_o_p_go = cnt_o_p_go + 1; last_o_p_go = o_p_go; end

    integer errors = 0, checks = 0;
    task check(input [8*48-1:0] name, input [31:0] got, input [31:0] exp);
        begin
            checks = checks + 1;
            if (got !== exp) begin
                errors = errors + 1;
                $display("FAIL %0s: got %h expected %h", name, got, exp);
            end
        end
    endtask
    task axi_write(input [31:0] adr, input [31:0] dat, input [3:0] stb);
        begin
            @(posedge clk); awaddr <= adr; wdata <= dat; wstrb <= stb;
            awvalid <= 1; wvalid <= 1; bready <= 1;
            @(posedge clk); while (!awready) @(posedge clk);
            awvalid <= 0; wvalid <= 0;
            while (!bvalid) @(posedge clk);
            @(posedge clk); bready <= 0;
        end
    endtask
    task axi_read(input [31:0] adr, output [31:0] dat);
        begin
            @(posedge clk); araddr <= adr; arvalid <= 1; rready <= 1;
            @(posedge clk); while (!arready) @(posedge clk);
            arvalid <= 0;
            while (!rvalid) @(posedge clk);
            dat = rdata; @(posedge clk); rready <= 0;
        end
    endtask

    reg [31:0] v;
    initial begin
        repeat (4) @(posedge clk); rstn <= 1; repeat (2) @(posedge clk);

        // 1) Reset values
        axi_read(32'h40002000, v); check("EV reset", v, 32'h00000000);
        axi_read(32'h40002004, v); check("P reset", v, 32'h00000000);

        // ---- EV
        @(posedge clk) i_ev_e <= 32'hFFFFFFFF; @(posedge clk) i_ev_e <= 0;
        axi_read(32'h40002000, v); check("EV.E set", v, 32'hFFFFFFFF);
        check("o_irq set by E", o_irq, 1);
        axi_write(32'h40002000, 32'hFFFFFFFF, 4'hF);
        axi_read(32'h40002000, v); check("EV.E W1C", v, 32'h00000000);
        check("o_irq cleared", o_irq, 0);

        // ---- P
        cnt_o_p_go = 0;
        axi_write(32'h40002004, 32'hFFFFFFFF, 4'hF);
        repeat (3) @(posedge clk);
        check("o_p_go one pulse", cnt_o_p_go, 1);
        check("o_p_go value", last_o_p_go, 32'hFFFFFFFF);
        check("o_p_go idle", o_p_go, 0);

        // Final read-back of every register
        axi_read(32'h40002000, v); check("EV final", v, 32'h00000000);
        axi_read(32'h40002004, v); check("P final", v, 32'h00000000);

        $display("%0d checks, %0d errors: %0s", checks, errors, errors ? "FAILED" : "PASSED");
        $finish;
    end
    initial begin #2000000; $display("TIMEOUT"); $finish; end
endmodule
`default_nettype wire
